SELECT DISTINCTROW Имена_станций.NAME, w.OES, w.YEAR, w.NUST, w.E, w.EOTP, w.EURT, w.EUST, w.Q, w.TURT, w.TUST, w.B, w.GAZ, w.MAZUT, w.TORF, w.SLAN, w.gtt AS Выражение1, w.PROCH, w.UGOL, w.DON, w.PODM, w.PECH, w.ARKT, w.KUZN, w.URAL, w.BASHK, w.ekib AS Выражение2, w.KARAG, w.KAN, w.IRKUT, w.HAK, w.TUV, w.BUR, w.CHIT, w.ner AS Выражение3, w.raich AS Выражение4, w.URG, w.PRIM, w.LUCH, w.MAG, w.SAH, w.QOTR, w.EWTP, w.NT AS NT, Имена_ОЭС.name AS oesname, wd.nazar AS nazar, wd.ibor AS ibor, wd.berez AS berez, wd.per AS per, wd.gusin AS gusin, wd.tugn AS tugn, wd.azey AS azey, wd.cher AS cher, wd.vork AS vork, wd.int AS [int], wd.sver AS sver, wd.chel AS chel, wd.kizel AS kizel, wd.kuzngd AS kuzngd, wd.kuznt AS kuznt, wd.kuznss AS kuznss, wd.kuznun AS kuznun, Имена_областей.АО AS oblname, w.OBL, Имена_станций.ordnumb
FROM ((([Рабочий(станции)] AS w INNER JOIN Имена_ОЭС ON w.OES=Имена_ОЭС.oes) LEFT JOIN [Рабочий(доп_угли)] AS wd ON (w.YEAR=wd.YEAR) AND (w.NUMB1120=wd.NUMB1120)) INNER JOIN Имена_областей ON w.OBL=Имена_областей.OBL) INNER JOIN Имена_станций ON w.NUMB1120=Имена_станций.NUMB
WHERE (((w.YEAR)>0) AND ((Имена_станций.MAIN)=0 Or (Имена_станций.MAIN) Is Null))
ORDER BY Имена_станций.ordnumb;
